# The city's road graph, as the game would expose it: for each intersection, its neighbours.
ROADS = {
    "A": ["B", "C"],
    "B": ["A", "D"],
    "C": ["A", "D"],
    "D": ["B", "C"],
}

# The game's own traffic numbers, refreshed every frame or so.
traffic = {
    "A": {"queue": 3, "wait": 4.0},   # vehicles waiting, average wait in seconds
    "B": {"queue": 18, "wait": 26.0},
    "C": {"queue": 1, "wait": 2.0},
    "D": {"queue": 11, "wait": 15.0},
}

def set_light(intersection, phase, green):
    """What the game does with the answer: swap the phase and time it."""
    print(f"{intersection}: {phase} for {green:.0f}s")

# --- Kinloom ---

# Each intersection decides for itself, every frame, from what it can see right now.
# The example is the offline answer: green for the busiest approach, 10-60 s.
decisions = kl.decide(
    "TRAFFIC_LIGHTS",
    {"intersections": {name: traffic[name] for name in ROADS}},
    {
        name: {"phase": ["north-south", "east-west"], "green": [10.0, 60.0]}
        for name in ROADS
    },
)

# Where the game would apply it.
for name, light in decisions.items():
    set_light(name, light["phase"], light["green"])

# --- stand-in for the game (plain Python, no engine) ---

# a junction: how many cars are waiting on each approach, and which way is green now
junctions = {
    "J1": {"north": 12, "east": 3, "south": 2, "west": 4, "green": "north"},
    "J2": {"north": 1, "east": 1, "south": 1, "west": 1, "green": "east"},
    "J3": {"north": 0, "east": 18, "south": 6, "west": 9, "green": "west"},
}

def queue_lengths(junction):
    """cars waiting per approach, as a fraction of a jammed approach (0.0..1.0)"""
    return {d: min(cars / 20.0, 1.0) for d, cars in junction.items() if d != "green"}

def set_green(junction_name, approach):
    junctions[junction_name]["green"] = approach

# --- what the game asks Kinloom, once, where the loop/lights update would be ---

for name, junction in junctions.items():
    plan = kl.decide(
        f"TRAFFIC LIGHT {name}",
        {"queues": queue_lengths(junction), "green": junction["green"]},
        {"green": ["north", "east", "south", "west"],
         "seconds": [5, 60],
         "reason": "text"},
    )
    set_green(name, plan["green"])

from kinloom import Kinloom

kl = Kinloom()

# --- stand-in for the game ---
# one intersection: how many cars are queued per approach, and how long each light has been green
intersections = {
    "main_st": {"north": 12, "south": 9, "east": 3, "west": 2, "green_for": 24.0},
    "harbor":  {"north": 1,  "south": 2, "east": 14, "west": 11, "green_for": 6.0},
}

def total_waiting(i):
    return i["north"] + i["south"] + i["east"] + i["west"]

def busiest(i):
    return max(("north", "south", "east", "west"), key=lambda d: i[d])

# --- the AI: one call per intersection, instant every frame, refreshed in the background ---
def plan_lights(name, i):
    return kl.decide(
        f"LIGHTS-{name}",
        {"queued": {"north": i["north"], "south": i["south"], "east": i["east"], "west": i["west"]},
         "green_for": i["green_for"],
         "total_waiting": total_waiting(i)},
        {"phase": ["north_south", "east_west"],
         "green_seconds": [4.0, 45.0],
         "all_red": False},
    )

# where the game would call it, once per intersection per frame
plans = {name: plan_lights(name, i) for name, i in intersections.items()}

for name, plan in plans.items():
    print(name, "->", plan, "| busiest right now:", busiest(intersections[name]))

