from kinloom import Kinloom

kl = Kinloom()

# --- stand-in for the game (example values, no engine) ---
PLAYER = {"x": 0.0, "y": 0.0}
enemies = [{"id": i, "x": float(i % 10), "y": float(i // 10), "hp": 0.9, "damage_taken": 0.0, "damage_dealt": 0.0}
           for i in range(200)]

def player_hp():
    return 1.0

def dist_to_player(e):
    return ((e["x"] - PLAYER["x"]) ** 2 + (e["y"] - PLAYER["y"]) ** 2) ** 0.5

def allies_near(e, radius=15.0):
    return sum(1 for o in enemies if o is not e and dist_to_player(o) < radius)

def move(e, action, args):
    e["last_action"] = action
    e["last_args"] = args

# --- one mind for every enemy, declared once ---
kl.mind("grunt", "a nervous shooter who hates dying and loves an unfair fight",
        senses={"hp": [0.0, 1.0], "dist": [0.0, 60.0], "allies": [0, 20], "player_hp": [0.0, 1.0]},
        actions={"flee": {}, "flank": {"side": ["left", "right"]}, "hold": {}, "push": {}},
        rules={"flee": ["hp low"],
               "flank": {"score": 0.9, "when": ["allies above 3"]},
               "push": {"score": 0.5, "when": ["player_hp low"]},
               "hold": {"score": 0.2}},
        learn=30)

# --- the game loop, one frame ---
for e in enemies:
    senses = {"hp": e["hp"], "dist": dist_to_player(e), "allies": allies_near(e), "player_hp": player_hp()}
    a = kl.think("grunt", senses, who=e["id"])
    move(e, a["action"], a.get("args", {}))

# --- after the frame, tell the mind what each choice earned ---
for e in enemies:
    earned = e["damage_dealt"] - e["damage_taken"]
    kl.reward(e["id"], earned, done=e["hp"] <= 0.0)

