from kinloom import Kinloom

kl = Kinloom()

# --- stand-in for the game -------------------------------------------------
BUILDINGS = []          # what exists in the world


def build(kind: str = "farm", count: int = 1, near: str = "here"):
    """build `count` buildings of `kind` near a place"""
    for _ in range(count):
        BUILDINGS.append({"kind": kind, "near": near})
    return BUILDINGS[-1]


def demolish(kind: str = "farm", near: str = "here"):
    """tear down buildings of `kind` near a place"""
    global BUILDINGS
    doomed = [b for b in BUILDINGS if b["kind"] == kind and b["near"] == near]
    BUILDINGS = [b for b in BUILDINGS if b not in doomed]
    return len(doomed)


def send_workers(count: int = 1, to: str = "here"):
    """move `count` workers to a place"""
    return {"workers": count, "to": to}


def stop_all():
    """cancel whatever is under way"""
    return "stopped"


# The player's side of the world, as the planner sees it: places, resources, what stands where.
WORLD = {
    "places": ["the river", "the north hill", "the old quarry", "the town square"],
    "gold": 40,
    "workers": 6,
    "standing": [{"kind": "farm", "near": "the town square"}],
}

# --- the character that turns typed words into actions ---------------------
kl.character("FOREMAN", "the player's foreman; takes orders and gets them done",
             tools=[build, demolish, send_workers, stop_all])

# --- where the game would call it ------------------------------------------
typed = "build two farms near the river, then send three workers there"

kl.event("Player's order: " + typed, about=["FOREMAN"])
for tool, args in kl.act("FOREMAN", {"order": typed, "world": WORLD}):
    # Python tools already ran inside act(); this loop is for tools given as names/dicts
    if tool == "build":
        build(**args)
    elif tool == "demolish":
        demolish(**args)
    elif tool == "send_workers":
        send_workers(**args)
    elif tool == "stop_all":
        stop_all()
    print(tool, args)

