# --- stand-ins for the game (plain Python, no engine) ---
world = {"farms": [], "roads": [], "river_at": (10, 4), "gold": 120}


def build(kind: str = "farm", count: int = 1, near: str = "river"):
    """build `count` of `kind` near a landmark"""
    cost = {"farm": 20, "road": 10}.get(kind, 15) * count
    if world["gold"] < cost:
        return {"ok": False, "why": "not enough gold"}
    world["gold"] -= cost
    for i in range(count):
        world[kind + "s" if kind != "farm" else "farms"].append({"near": near, "at": (i, i)})
    return {"ok": True, "built": count, "kind": kind, "near": near, "gold_left": world["gold"]}


def demolish(kind: str = "farm", count: int = 1):
    """tear down `count` of `kind`"""
    return {"ok": True, "removed": count, "kind": kind}


def wait(turns: int = 1):
    """do nothing for a while"""
    return {"ok": True, "waited": turns}


# --- the player's command, turned into game actions ---
kl.character(
    "BUILDER",
    soul="the player's foreman; turns spoken orders into building work",
    tools=[build, demolish, wait],
    offline="Right away, boss.",
)

order = "build two farms near the river"

