from kinloom import Kinloom

kl = Kinloom()

# --- stand-in for the game (plain Python, no engine) -------------------------

# what players did at the market today, per item
trades_today = {
    "wood": {"bought": 20, "sold": 400},   # players are dumping wood -> price should fall
    "iron": {"bought": 310, "sold": 15},   # players are hoarding iron -> price should rise
    "bread": {"bought": 90, "sold": 85},   # steady
}

# the market's current prices
prices = {"wood": 12, "iron": 40, "bread": 6}

# a rough pressure signal per item: >0 means demand exceeds supply
def pressure(bought, sold):
    return (bought - sold) / max(bought + sold, 1)

# the game's own way to apply a new price
def set_price(item, price):
    prices[item] = price
    print(f"price of {item} is now {price}")

# --- the game would call this at the end of each market day ------------------

kl.character("MARKET", "an economist keeping prices fair and interesting", every=30)

situation = {
    "prices": prices,
    "wood_pressure": round(pressure(trades_today["wood"]["bought"], trades_today["wood"]["sold"]), 2),
    "iron_pressure": round(pressure(trades_today["iron"]["bought"], trades_today["iron"]["sold"]), 2),
    "bread_pressure": round(pressure(trades_today["bread"]["bought"], trades_today["bread"]["sold"]), 2),
    "player_gold": 5000,
}

new_prices = kl.decide(
    "MARKET",
    situation,
    {"wood": [1, 20], "iron": [5, 60], "bread": [1, 15], "event": ["none", "shortage", "festival"]},
)

