from kinloom import Kinloom

kl = Kinloom()

# --- stand-in for the game -------------------------------------------------
# The shooter's history: where each of their last penalties went, and how often
# they placed it there. In the game this comes from the shooter's stats.
shooter_history = [
    {"goal": "left",   "power": 0.9},
    {"goal": "left",   "power": 0.7},
    {"goal": "right",  "power": 0.8},
    {"goal": "center", "power": 0.5},
    {"goal": "left",   "power": 0.95},
]

def placement_counts(history):
    counts = {"left": 0, "center": 0, "right": 0}
    for shot in history:
        counts[shot["goal"]] += 1
    return counts

def average_power(history):
    if not history:
        return 0.0
    return sum(shot["power"] for shot in history) / len(history)

# The keeper's own read on the taker, plus the scoreline pressure.
def keeper_situation(history, score_diff, minute):
    return {
        "shots_seen": len(history),
        "placement_counts": placement_counts(history),
        "avg_power": round(average_power(history), 2),
        "score_diff": score_diff,          # negative = keeper's team is behind
        "minute": minute,
    }

# --- the call the game makes ----------------------------------------------
# The keeper picks a dive side from the shooter's history, every penalty.
dive = kl.decide(
    "GOALKEEPER",
    keeper_situation(shooter_history, score_diff=-1, minute=78),
    {
        "dive": ["left", "center", "right"],
        "commitment": [0.0, 1.0],   # 1.0 = full dive, 0.0 = stay and react
        "reason": "text",
    },
)

# The game uses the answer as it is:
print(dive["dive"], dive["commitment"], dive["reason"])

