kl = Kinloom()

# --- stand-in for the game -------------------------------------------------
# Each player has a language the game already knows about them.
PLAYERS = {
    "ana": {"language": "Spanish"},
    "kenji": {"language": "Japanese"},
    "mary": {"language": "English"},
}

# A chat message as the game produces it.
incoming = {"from": "ana", "text": "¿Dónde está la llave del sótano?"}

def deliver(to, text):
    print(f"-> {to}: {text}")
# ---------------------------------------------------------------------------

def translate(message, to_player):
    """One player's chat message, in the language another player reads."""
    sender = message["from"]
    sender_lang = PLAYERS[sender]["language"]
    reader_lang = PLAYERS[to_player]["language"]
    return kl.create(
        "translate a chat message between two players",
        {"text": "text"},
        context={
            "message": message["text"],
            "from_language": sender_lang,
            "to_language": reader_lang,
        },
    )["text"]


def relay(message):
    """Send the message to everyone who speaks something else."""
    sender = message["from"]
    for player in PLAYERS:
        if player == sender:
            continue
        if PLAYERS[player]["language"] == PLAYERS[sender]["language"]:
            deliver(player, message["text"])
        else:
            deliver(player, translate(message, player))


# where the game would: a message arrives, everyone else gets it
relay(incoming)

# --- stand-in for the game -------------------------------------------------
LANGUAGES = {"Ana": "en", "Ivo": "pt", "Mei": "zh"}     # who speaks what
chat_log = []                                            # the shared chat the game draws

def broadcast(speaker: str, text: str):
    """put a line into the shared chat everyone sees"""
    chat_log.append((speaker, text))

def last_line():
    return chat_log[-1] if chat_log else ("", "")

def send_pressed():
    """the game says a player hit Enter on their typed line"""
    return "Ana", "the bridge is out past the mill, take the north road"

# --- the translator: one character, one soul, no per-language prompts ------
kl.lore(["Ashford sits on the north road.", "Players chat in English, Portuguese or Chinese."])
kl.character("TALIA", soul="a patient interpreter standing between travellers, who renders every line faithfully "
                           "into the listener's language and keeps names, numbers and slang intact",
             offline="...")   # nothing to say: the game still shows the original line

def translate(speaker: str, text: str) -> str:
    """what the listener would hear, in their own language"""
    listener_lang = "en" if LANGUAGES[speaker] != "en" else "pt"   # the other side of the conversation
    return kl.chat("TALIA", f"Say in {listener_lang}: {text}", {"speaker": speaker, "listener_lang": listener_lang},
                   speaker=speaker)

